const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const craighead = ee.FeatureCollection('TIGER/2018/Counties')
    .filter(ee.Filter.and(
      ee.Filter.eq('STATEFP', '05'), // Arkansas state FIPS code
      ee.Filter.eq('NAME', 'Craighead')
    ))
    .first();

  const jackson = ee.FeatureCollection('TIGER/2018/Counties')
    .filter(ee.Filter.and(
      ee.Filter.eq('STATEFP', '05'), // Arkansas state FIPS code
      ee.Filter.eq('NAME', 'Jackson')
    ))
    .first();

  if (!craighead || !jackson) {
    console.log("Error: Could not retrieve county geometries.");
    console.log("D");
    return;
  }

  const studyArea = craighead.geometry().intersection(jackson.geometry());

  // Define date ranges for analysis
  const date2023_start = '2023-04-01';
  const date2023_end = '2023-04-30'; // Wider range to increase chance of finding an image
  const date2025_start = '2025-04-01';
  const date2025_end = '2025-04-30'; // Wider range to increase chance of finding an image

  // 2. Data Acquisition & Check
  const s2_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitmask = 1 << 10;
    const cirrusBitmask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitmask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitmask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B8', 'B3', 'B2', 'B11']) // NIR, Green, Blue, SWIR1
      .copyProperties(image, ['system:time_start']);
  }

  // Filter images for 2023
  let collection2023 = s2_collection
    .filterBounds(studyArea)
    .filterDate(date2023_start, date2023_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds);

  const size2023 = await collection2023.size().getInfo();
  console.log(`2023 Images in collection (April 1-30): ${size2023}`);

  // Filter images for 2025 (future date)
  let collection2025 = s2_collection
    .filterBounds(studyArea)
    .filterDate(date2025_start, date2025_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds);

  const size2025 = await collection2025.size().getInfo();
  console.log(`2025 Images in collection (April 1-30): ${size2025}`);

  // Check for empty collection due to future date
  if (size2025 === 0) {
    console.log("No images found for 2025 as it is a future date.");
    console.log("C1"); // Empty Collection
    return;
  }

  // At this point, if we reached here, it implies the 2025 check somehow passed,
  // which is unexpected given 2025 is in the future. The above C1 should catch it.
  // This section would only execute if the date was not in the future.
  // We'll proceed with the rest of the analysis as a fallback, but the C1 is the expected outcome.

  if (size2023 === 0) {
    console.log("No images found for 2023 in the specified period.");
    console.log("C1"); // Empty Collection
    return;
  }

  // Select the least cloudy image for each year if multiple exist, or take the median.
  // For simplicity and robustness against single cloudy images, we'll take a median composite.
  const image2023 = collection2023.median();
  const image2025 = collection2025.median(); // This will likely be an empty image due to size2025=0

  // 3. Processing: Calculate NDWI and water area
  function calculateNDWI(image) {
    // NDWI = (Green - NIR) / (Green + NIR)
    return image.normalizedDifference(['B3', 'B8']).rename('NDWI');
  }

  function getWaterArea(image, geometry) {
    const ndwi = calculateNDWI(image);
    // Use a common NDWI threshold for water (e.g., > 0)
    const water = ndwi.gt(0.0).rename('water');

    // Calculate pixel area in square meters.
    // Sentinel-2 has 10m resolution for visible and NIR bands.
    const pixelArea = ee.Image.pixelArea();
    const waterAreaImage = water.multiply(pixelArea).updateMask(water); // Mask non-water pixels

    // Reduce region to get the total water area
    const stats = waterAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10, // Sentinel-2 resolution for NDWI bands (Green and NIR)
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Use WGS84 as CRS for consistency
      tileScale: 16
    });

    const area = stats.get('water');
    return area;
  }

  // Calculate water extent for 2023
  const waterArea2023_val = await getWaterArea(image2023, studyArea).getInfo();
  let validPixels2023_count = await image2023.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: studyArea,
    scale: 10,
    maxPixels: 1e9,
    tileScale: 16
  }).get('B3').getInfo();

  console.log(`2023 Water Area (sq m): ${waterArea2023_val}`);
  console.log(`2023 Valid Pixels: ${validPixels2023_count}`);

  if (validPixels2023_count === 0) {
    console.log("No valid pixels for 2023 after cloud masking/processing.");
    console.log("C2");
    return;
  }
  if (waterArea2023_val === null || isNaN(waterArea2023_val)) {
    console.log("Calculation failed for 2023 water area.");
    console.log("C3");
    return;
  }

  // Calculate water extent for 2025
  const waterArea2025_val = await getWaterArea(image2025, studyArea).getInfo();
  let validPixels2025_count = await image2025.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: studyArea,
    scale: 10,
    maxPixels: 1e9,
    tileScale: 16
  }).get('B3').getInfo();

  console.log(`2025 Water Area (sq m): ${waterArea2025_val}`);
  console.log(`2025 Valid Pixels: ${validPixels2025_count}`);

  if (validPixels2025_count === 0) {
    console.log("No valid pixels for 2025 after cloud masking/processing.");
    console.log("C2");
    return;
  }
  if (waterArea2025_val === null || isNaN(waterArea2025_val)) {
    console.log("Calculation failed for 2025 water area.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  if (waterArea2025_val > waterArea2023_val) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

